        .with_env_filter(
            tracing_subscriber::EnvFilter::from_default_env()
                .add_directive(filter_level.parse().unwrap_or_else(|_| "info".parse().unwrap())),
        )
        .init();

    // Validate conflicting options
    if args.force && args.no_clobber {
        return Err(anyhow!("--force and --no-clobber are mutually exclusive"));
    }

    // Check paths
