fn perform_copy(sources: &[PathBuf], dest: &Path, args: &Args) -> Result<()> {
    // Check if destination exists and is a directory
    let dest_is_dir = dest.exists() && dest.is_dir();
    let dest_exists = dest.exists();

    // Handle no-target-directory flag
    if args.no_target_directory && sources.len() > 1 {
        return Err(anyhow!("Invalid source: Cannot specify multiple sources with --no-target-directory"));
    }

    if args.no_target_directory {
        // Single source to non-directory destination
        info!("Copying source \"{}\" to \"{}\"", sources[0].display(), dest.display());
        copy_single_source(&sources[0], dest, args)?;
    } else if sources.len() == 1 {
        let source = &sources[0];

        // Check if source is a directory
        if source.is_dir() && !args.recursive {
            return Err(anyhow!("Invalid source: Source is a directory; use -r/--recursive to copy directories"));
        }

        // Check if source and dest are the same
        if let Ok(source_meta) = fs::metadata(source) {
            if let Ok(dest_meta) = fs::metadata(dest) {
                #[cfg(unix)]
                {
                    use std::os::unix::fs::MetadataExt;
                    if source_meta.ino() == dest_meta.ino() && source_meta.dev() == dest_meta.dev() {
                        return Err(anyhow!("Invalid source: Cannot copy a directory into itself"));
                    }
                }
            }
        }

        info!("Copying source \"{}\" to \"{}\"", source.display(), dest.display());

        if dest_is_dir && !args.no_target_directory {
            // Copy into directory
            let dest_file = dest.join(source.file_name().ok_or(anyhow!("Invalid source path"))?);
            copy_single_source(source, &dest_file, args)?;
        } else {
            // Copy with destination name
            copy_single_source(source, dest, args)?;
        }
    } else {
        // Multiple sources - destination must be directory
        if !dest_is_dir {
            return Err(anyhow!("Invalid destination: Destination must be a directory when copying multiple sources"));
        }

        for source in sources {
            info!("Copying source \"{}\" to directory", source.display());
            let dest_file = dest.join(source.file_name().ok_or(anyhow!("Invalid source path"))?);
            copy_single_source(source, &dest_file, args)?;
        }
    }

    Ok(())
}

fn copy_single_source(source: &Path, dest: &Path, args: &Args) -> Result<()> {
    if source.is_dir() {
        copy_directory(source, dest, args)
    } else if source.is_symlink() && !args.dereference {
        copy_symlink(source, dest, args)
    } else {
        copy_file(source, dest, args)
    }
}

fn copy_file(source: &Path, dest: &Path, args: &Args) -> Result<()> {
    // Check for existing file
    if dest.exists() && args.no_clobber {
        return Err(anyhow!("Destination Exists: Destination file exists and --no-clobber is set., {}", dest.display()));
    }

    // Create destination parent directory if needed
    if let Some(parent) = dest.parent() {
        if !parent.exists() && parent != Path::new("") {
            fs::create_dir_all(parent)?;
        }
    }

    // Handle backup
    if dest.exists() && args.backup != "none" && args.backup != "off" {
        create_backup(dest, &args.backup)?;
    }

    debug!("Attempting reflink from File {{ fd: 3, path: {}, read: true, write: false }}->File {{ fd: 4, path: {}, read: false, write: true }}", source.display(), dest.display());

    // Simple file copy
    fs::copy(source, dest)?;

    debug!("Reflink File {{ fd: 4, path: {}, read: false, write: true }} succeeded", dest.display());

    // Copy metadata
    copy_metadata(source, dest, args)?;

    // Sync if requested
    if args.fsync {
        let file = fs::File::open(dest)?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt;
            nix::fcntl::fsync(file.as_raw_fd())?;
        }
    }

    Ok(())
}

fn copy_symlink(source: &Path, dest: &Path, args: &Args) -> Result<()> {
    // Check for existing file
    if dest.exists() && args.no_clobber {
        return Err(anyhow!("Destination Exists: Destination file exists and --no-clobber is set., {}", dest.display()));
    }

    // Create destination parent directory if needed
    if let Some(parent) = dest.parent() {
        if !parent.exists() && parent != Path::new("") {
            fs::create_dir_all(parent)?;
        }
    }

    // Handle backup
    if dest.exists() && args.backup != "none" && args.backup != "off" {
        create_backup(dest, &args.backup)?;
    }

    // Read the symlink target
    let target = fs::read_link(source)?;

    // Create the symlink at destination
    if dest.exists() {
        fs::remove_file(dest)?;
    }
    unix_fs::symlink(&target, dest)?;

    // Copy metadata (but symlink metadata is tricky)
    // Most systems don't support chmod on symlinks, so we skip that

    Ok(())
}

fn copy_directory(source: &Path, dest: &Path, args: &Args) -> Result<()> {
    // Check if source and dest are the same
    if let Ok(source_meta) = fs::metadata(source) {
        if let Ok(dest_meta) = fs::metadata(dest) {
            #[cfg(unix)]
            {
                use std::os::unix::fs::MetadataExt;
                if source_meta.ino() == dest_meta.ino() && source_meta.dev() == dest_meta.dev() {
                    return Err(anyhow!("Invalid source: Cannot copy a directory into itself"));
                }
            }
        }
    }

    // Check for existing file
    if dest.exists() && args.no_clobber {
        return Err(anyhow!("Destination Exists: Destination file exists and --no-clobber is set., {}", dest.display()));
    }

    // Create destination directory if it doesn't exist
    if !dest.exists() {
        fs::create_dir_all(dest)?;
    }

    // Walk the source directory
    for entry in walkdir::WalkDir::new(source)
        .into_iter()
        .filter_map(|e| e.ok())
    {
        let path = entry.path();
        let relative = path.strip_prefix(source)?;
        let dest_path = dest.join(relative);

        if path.is_dir() {
            if !dest_path.exists() {
                fs::create_dir(&dest_path)?;
                copy_metadata(path, &dest_path, args)?;
            }
        } else if path.is_symlink() && !args.dereference {
            copy_symlink(path, &dest_path, args)?;
        } else {
            copy_file(path, &dest_path, args)?;
        }
    }

    // Copy source directory metadata
    copy_metadata(source, dest, args)?;

    Ok(())
}

fn copy_metadata(source: &Path, dest: &Path, args: &Args) -> Result<()> {
    let metadata = fs::metadata(source)?;

    debug!("Copy xattr \"security.selinux\"");
    // TODO: Implement xattr copying

    if !args.no_perms {
        debug!("Performing permissions copy");
        copy_permissions(source, dest)?;
    }

    if !args.no_timestamps {
        debug!("Performing timestamp copy");
        copy_timestamps(source, dest, &metadata)?;
    }

    if args.ownership {
        // Try to copy ownership
        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt;
            let uid = metadata.uid();
            let gid = metadata.gid();
            let _ = nix::unistd::chown(dest, Some(nix::unistd::Uid::from_raw(uid)), Some(nix::unistd::Gid::from_raw(gid)));
        }
    }

    Ok(())
}

fn copy_permissions(source: &Path, dest: &Path) -> Result<()> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let metadata = fs::metadata(source)?;
        let perms = fs::Permissions::from_mode(metadata.permissions().mode());
        fs::set_permissions(dest, perms)?;
    }
    Ok(())
}

fn copy_timestamps(source: &Path, dest: &Path, metadata: &fs::Metadata) -> Result<()> {
    let modified = metadata.modified()?;
    let accessed = metadata.accessed()?;

    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        use std::time::UNIX_EPOCH;

        let modified_secs = modified.duration_since(UNIX_EPOCH)?.as_secs() as i64;
        let accessed_secs = accessed.duration_since(UNIX_EPOCH)?.as_secs() as i64;

        let times = [
            nix::sys::stat::TimeSpec::new(accessed_secs, 0),
            nix::sys::stat::TimeSpec::new(modified_secs, 0),
        ];

        let _ = nix::sys::stat::utimensat(
            None,
            dest,
            &times,
            nix::fcntl::AtFlags::empty(),
        );
    }

    Ok(())
}

fn create_backup(path: &Path, backup_type: &str) -> Result<()> {
    if backup_type == "none" || backup_type == "off" {
        return Ok(());
    }

    if backup_type == "numbered" || backup_type == "auto" {
        // Find the highest numbered backup
        let mut num = 1;
        loop {
            let backup_path = PathBuf::from(format!("{}.~{}~", path.display(), num));
            if !backup_path.exists() {
                fs::rename(path, &backup_path)?;
                break;
            }
            num += 1;
            if num > 1000 {
                return Err(anyhow!("Too many backup files"));
            }
        }
    }

    Ok(())
}

