    if backup_type == "none" || backup_type == "off" {
        return Ok(());
    }

    if backup_type == "numbered" || backup_type == "auto" {
        // Find the highest numbered backup
        let mut num = 1;
        loop {
            let backup_path = PathBuf::from(format!("{}.~{}~", path.display(), num));
