    let parsed_args = Args::from_env_args(args)?;

    let sources: Vec<PathBuf> = parsed_args.paths[..parsed_args.paths.len() - 1].to_vec();
    let dest = &parsed_args.paths[parsed_args.paths.len() - 1];

    perform_copy(&sources, dest, &parsed_args)?;

