        if dest_is_dir && !args.no_target_directory {
            // Copy into directory
            let dest_file = dest.join(source.file_name().ok_or("Invalid source path".to_string())?);
            copy_single_source(source, &dest_file, args)?;
        } else {
            // Copy with destination name
            copy_single_source(source, dest, args)?;
        }
