        let error_msg = format!("Destination Exists: Destination file exists and --no-clobber is set., {}", dest.display());
        if args.verbose >= 1 {
            eprintln!("07:02:21 [ERROR] Received error: {}", error_msg);
        }
        return Err(error_msg);
    }

    // Create destination parent directory if needed
    if let Some(parent) = dest.parent() {
        if !parent.exists() && parent != Path::new("") {
            fs::create_dir_all(parent).map_err(|e| e.to_string())?;
        }
    }

    // Handle backup
    if dest.exists() && args.backup != "none" && args.backup != "off" {
        create_backup(dest, &args.backup)?;
    }

    if args.verbose >= 3 {
        eprintln!("07:02:22 [DEBUG] (4) libxcp::drivers::parfile: Attempting reflink from File {{ fd: 3, path: {}, read: true, write: false }}->File {{ fd: 4, path: {}, read: false, write: true }}", source.display(), dest.display());
