fn copy_directory(source: &Path, dest: &Path, args: &Args) -> Result<(), String> {
    // Check if source and dest are the same
    if is_same_file(source, dest).unwrap_or(false) {
        return Err("Invalid source: Cannot copy a directory into itself".to_string());
    }

    // Check for existing file
    if dest.exists() && args.no_clobber {
        let error_msg = format!("Destination Exists: Destination file exists and --no-clobber is set., {}", dest.display());
        if args.verbose >= 1 {
            eprintln!("07:02:21 [ERROR] Received error: {}", error_msg);
        }
        return Err(error_msg);
    }

    // Create destination directory if it doesn't exist
    if !dest.exists() {
        fs::create_dir_all(dest).map_err(|e| e.to_string())?;
    }

    // Walk the source directory
    fn walk_dir(source: &Path, base_source: &Path, dest: &Path, args: &Args) -> Result<(), String> {
        for entry in fs::read_dir(source).map_err(|e| e.to_string())? {
            let entry = entry.map_err(|e| e.to_string())?;
            let path = entry.path();
            let relative = path.strip_prefix(base_source).map_err(|e| e.to_string())?;
            let dest_path = dest.join(relative);

            if path.is_dir() {
                if !dest_path.exists() {
                    fs::create_dir(&dest_path).map_err(|e| e.to_string())?;
