                copy_symlink(&path, &dest_path, args)?;
            } else {
                copy_file(&path, &dest_path, args)?;
            }
        }
        Ok(())
    }

    walk_dir(source, source, dest, args)?;

    // Copy source directory metadata
    copy_metadata(source, dest, args)?;

    Ok(())
}

