        TimeVal { tv_sec: atime, tv_usec: 0 },
        TimeVal { tv_sec: mtime, tv_usec: 0 },
    ];

    extern "C" {
        fn utimes(path: *const u8, times: *const [i64; 2]) -> i32;
    }

    let result = unsafe {
