            return Err("Invalid source: Source is a directory; use -r/--recursive to copy directories".to_string());
        }

        // Check if source and dest are the same
        if is_same_file(source, dest).unwrap_or(false) {
            return Err("Invalid source: Cannot copy a directory into itself".to_string());
        }

        if args.verbose >= 1 {
            eprintln!("07:02:21 [INFO] Copying source \"{}\" to \"{}\"", source.display(), dest.display());
