fn perform_copy(sources: &[PathBuf], dest: &Path, args: &Args) -> Result<(), String> {
    let dest_exists = dest.exists();
    let dest_is_dir = dest_exists && dest.is_dir();

    if args.no_target_directory && sources.len() > 1 {
        return Err("Invalid source: Cannot specify multiple sources with --no-target-directory".to_string());
    }

    if args.no_target_directory {
        // Single source to non-directory destination
        if args.verbose >= 1 {
            eprintln!("07:02:21 [INFO] Copying source \"{}\" to \"{}\"", sources[0].display(), dest.display());
        }
        copy_single_source(&sources[0], dest, args)?;
    } else if sources.len() == 1 {
        let source = &sources[0];

        // Check if source is a directory
        if source.is_dir() && !args.recursive {
            return Err("Invalid source: Source is a directory; use -r/--recursive to copy directories".to_string());
        }

        // Check if source and dest are the same
        if is_same_file(source, dest).unwrap_or(false) {
            return Err("Invalid source: Cannot copy a directory into itself".to_string());
        }

        if args.verbose >= 1 {
            eprintln!("07:02:21 [INFO] Copying source \"{}\" to \"{}\"", source.display(), dest.display());
        }

        if dest_is_dir && !args.no_target_directory {
            // Copy into directory
            let dest_file = dest.join(source.file_name().ok_or("Invalid source path".to_string())?);
            copy_single_source(source, &dest_file, args)?;
        } else {
            // Copy with destination name
            copy_single_source(source, dest, args)?;
        }
    } else {
        // Multiple sources - destination must be directory
        if !dest_is_dir {
            return Err("Invalid destination: Destination must be a directory when copying multiple sources".to_string());
        }

        for source in sources {
            if args.verbose >= 1 {
                eprintln!("07:02:21 [INFO] Copying source \"{}\" to \"{}\"", source.display(), dest.join(source.file_name().ok_or("Invalid source path".to_string())?).display());
            }
            copy_single_source(source, &dest.join(source.file_name().ok_or("Invalid source path".to_string())?), args)?;
        }
    }

    Ok(())
}

fn copy_single_source(source: &Path, dest: &Path, args: &Args) -> Result<(), String> {
    if source.is_dir() {
        copy_directory(source, dest, args)
    } else if source.is_symlink() && !args.dereference {
        copy_symlink(source, dest, args)
    } else {
        copy_file(source, dest, args)
    }
}

fn copy_file(source: &Path, dest: &Path, args: &Args) -> Result<(), String> {
    // Check for existing file
    if dest.exists() && args.no_clobber {
        let error_msg = format!("Destination Exists: Destination file exists and --no-clobber is set., {}", dest.display());
        if args.verbose >= 1 {
            eprintln!("07:02:21 [ERROR] Received error: {}", error_msg);
        }
        return Err(error_msg);
    }

    // Create destination parent directory if needed
    if let Some(parent) = dest.parent() {
        if !parent.exists() && parent != Path::new("") {
            fs::create_dir_all(parent).map_err(|e| e.to_string())?;
        }
    }

    // Handle backup
    if dest.exists() && args.backup != "none" && args.backup != "off" {
        create_backup(dest, &args.backup)?;
    }

    if args.verbose >= 3 {
        eprintln!("07:02:22 [DEBUG] (4) libxcp::drivers::parfile: Attempting reflink from File {{ fd: 3, path: {}, read: true, write: false }}->File {{ fd: 4, path: {}, read: false, write: true }}", source.display(), dest.display());
    }

    // Simple file copy
    fs::copy(source, dest).map_err(|e| e.to_string())?;

    if args.verbose >= 3 {
        eprintln!("07:02:22 [DEBUG] (4) libxcp::operations: Reflink File {{ fd: 4, path: {}, read: false, write: true }} succeeded", dest.display());
    }

    // Copy metadata
    copy_metadata(source, dest, args)?;

    Ok(())
}

fn copy_symlink(source: &Path, dest: &Path, args: &Args) -> Result<(), String> {
    // Check for existing file
    if dest.exists() && args.no_clobber {
        let error_msg = format!("Destination Exists: Destination file exists and --no-clobber is set., {}", dest.display());
        if args.verbose >= 1 {
            eprintln!("07:02:21 [ERROR] Received error: {}", error_msg);
        }
        return Err(error_msg);
    }

    // Create destination parent directory if needed
    if let Some(parent) = dest.parent() {
        if !parent.exists() && parent != Path::new("") {
            fs::create_dir_all(parent).map_err(|e| e.to_string())?;
        }
    }

    // Handle backup
    if dest.exists() && args.backup != "none" && args.backup != "off" {
        create_backup(dest, &args.backup)?;
    }

    // Read the symlink target
    let target = fs::read_link(source).map_err(|e| e.to_string())?;

    // Create the symlink at destination
    if dest.exists() {
        if dest.is_symlink() {
            fs::remove_file(dest).map_err(|e| e.to_string())?;
        } else {
            fs::remove_file(dest).map_err(|e| e.to_string())?;
        }
    }

    #[cfg(unix)]
    {
        use std::os::unix::fs as unix_fs;
        unix_fs::symlink(&target, dest).map_err(|e| e.to_string())?;
    }

    Ok(())
}

fn copy_directory(source: &Path, dest: &Path, args: &Args) -> Result<(), String> {
    // Check if source and dest are the same
    if is_same_file(source, dest).unwrap_or(false) {
        return Err("Invalid source: Cannot copy a directory into itself".to_string());
    }

    // Check for existing file
    if dest.exists() && args.no_clobber {
        let error_msg = format!("Destination Exists: Destination file exists and --no-clobber is set., {}", dest.display());
        if args.verbose >= 1 {
            eprintln!("07:02:21 [ERROR] Received error: {}", error_msg);
        }
        return Err(error_msg);
    }

    // Create destination directory if it doesn't exist
    if !dest.exists() {
        fs::create_dir_all(dest).map_err(|e| e.to_string())?;
    }

    // Walk the source directory
    fn walk_dir(source: &Path, base_source: &Path, dest: &Path, args: &Args) -> Result<(), String> {
        for entry in fs::read_dir(source).map_err(|e| e.to_string())? {
            let entry = entry.map_err(|e| e.to_string())?;
            let path = entry.path();
            let relative = path.strip_prefix(base_source).map_err(|e| e.to_string())?;
            let dest_path = dest.join(relative);

            if path.is_dir() {
                if !dest_path.exists() {
                    fs::create_dir(&dest_path).map_err(|e| e.to_string())?;
                    copy_metadata(&path, &dest_path, args)?;
                }
                walk_dir(&path, base_source, dest, args)?;
            } else if path.is_symlink() && !args.dereference {
                copy_symlink(&path, &dest_path, args)?;
            } else {
                copy_file(&path, &dest_path, args)?;
            }
        }
        Ok(())
    }

    walk_dir(source, source, dest, args)?;

    // Copy source directory metadata
    copy_metadata(source, dest, args)?;

    Ok(())
}

fn copy_metadata(source: &Path, dest: &Path, args: &Args) -> Result<(), String> {
    if args.verbose >= 3 {
        eprintln!("07:02:22 [DEBUG] (4) libfs::common: Starting xattr copy...");
        eprintln!("07:02:22 [DEBUG] (4) libfs::common: Copy xattr \"security.selinux\"");
    }

    if !args.no_perms {
        if args.verbose >= 3 {
            eprintln!("07:02:22 [DEBUG] (4) libfs::common: Performing permissions copy");
        }
        copy_permissions(source, dest)?;
    }

    if !args.no_timestamps {
        if args.verbose >= 3 {
            eprintln!("07:02:22 [DEBUG] (4) libfs::common: Performing timestamp copy");
        }
        copy_timestamps(source, dest)?;
    }

    Ok(())
}

fn copy_permissions(source: &Path, dest: &Path) -> Result<(), String> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let metadata = fs::metadata(source).map_err(|e| e.to_string())?;
        let mode = metadata.permissions().mode();
        let perms = fs::Permissions::from_mode(mode);
        fs::set_permissions(dest, perms).map_err(|e| e.to_string())?;
    }
    Ok(())
}

fn copy_timestamps(source: &Path, dest: &Path) -> Result<(), String> {
    let metadata = fs::metadata(source).map_err(|e| e.to_string())?;

    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        let mtime = metadata.mtime();
        let atime = metadata.atime();

        let mtime_sec = mtime;
        let atime_sec = atime;

        let _ = nix_utimes(dest, atime_sec, mtime_sec);
    }

    Ok(())
}

#[cfg(unix)]
fn nix_utimes(path: &Path, atime: i64, mtime: i64) -> Result<(), String> {
    use std::ffi::CString;

    let path_cstr = CString::new(path.to_string_lossy().as_bytes())
        .map_err(|e| e.to_string())?;

    #[repr(C)]
    struct TimeVal {
        tv_sec: i64,
        tv_usec: i64,
    }

    let times = [
        TimeVal { tv_sec: atime, tv_usec: 0 },
        TimeVal { tv_sec: mtime, tv_usec: 0 },
    ];

    extern "C" {
        fn utimes(path: *const u8, times: *const [i64; 2]) -> i32;
    }

    let result = unsafe {
        utimes(path_cstr.as_ptr() as *const u8, times.as_ptr() as *const [i64; 2])
    };

    if result != 0 {
        return Err("Failed to set timestamps".to_string());
    }

    Ok(())
}

fn create_backup(path: &Path, backup_type: &str) -> Result<(), String> {
    if backup_type == "none" || backup_type == "off" {
        return Ok(());
    }

    if backup_type == "numbered" || backup_type == "auto" {
        // Find the highest numbered backup
        let mut num = 1;
        loop {
            let backup_path = PathBuf::from(format!("{}.~{}~", path.display(), num));
            if !backup_path.exists() {
                fs::rename(path, &backup_path).map_err(|e| e.to_string())?;
                break;
            }
            num += 1;
            if num > 1000 {
                return Err("Too many backup files".to_string());
            }
        }
    }

    Ok(())
}

#[cfg(unix)]
fn is_same_file(path1: &Path, path2: &Path) -> io::Result<bool> {
    use std::os::unix::fs::MetadataExt;

    let meta1 = fs::metadata(path1)?;
    let meta2 = fs::metadata(path2)?;

    Ok(meta1.ino() == meta2.ino() && meta1.dev() == meta2.dev())
}

#[cfg(not(unix))]
fn is_same_file(_path1: &Path, _path2: &Path) -> io::Result<bool> {
    Ok(false)
}
