fn copy_permissions(source: &Path, dest: &Path) -> Result<(), String> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let metadata = fs::metadata(source).map_err(|e| e.to_string())?;
        let mode = metadata.permissions().mode();
        let perms = fs::Permissions::from_mode(mode);
        fs::set_permissions(dest, perms).map_err(|e| e.to_string())?;
    }
    Ok(())
}

fn copy_timestamps(source: &Path, dest: &Path) -> Result<(), String> {
    let metadata = fs::metadata(source).map_err(|e| e.to_string())?;

    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        let mtime = metadata.mtime();
        let atime = metadata.atime();

        let mtime_sec = mtime;
        let atime_sec = atime;

        let _ = nix_utimes(dest, atime_sec, mtime_sec);
    }

    Ok(())
}

#[cfg(unix)]
fn nix_utimes(path: &Path, atime: i64, mtime: i64) -> Result<(), String> {
    use std::ffi::CString;

    let path_cstr = CString::new(path.to_string_lossy().as_bytes())
        .map_err(|e| e.to_string())?;

    #[repr(C)]
    struct TimeVal {
        tv_sec: i64,
        tv_usec: i64,
    }

    let times = [
        TimeVal { tv_sec: atime, tv_usec: 0 },
        TimeVal { tv_sec: mtime, tv_usec: 0 },
    ];

    extern "C" {
        fn utimes(path: *const u8, times: *const [i64; 2]) -> i32;
    }

    let result = unsafe {
        utimes(path_cstr.as_ptr() as *const u8, times.as_ptr() as *const [i64; 2])
    };

    if result != 0 {
        return Err("Failed to set timestamps".to_string());
    }

    Ok(())
}

fn create_backup(path: &Path, backup_type: &str) -> Result<(), String> {
    if backup_type == "none" || backup_type == "off" {
        return Ok(());
    }

    if backup_type == "numbered" || backup_type == "auto" {
        // Find the highest numbered backup
        let mut num = 1;
        loop {
            let backup_path = PathBuf::from(format!("{}.~{}~", path.display(), num));
            if !backup_path.exists() {
                fs::rename(path, &backup_path).map_err(|e| e.to_string())?;
                break;
            }
            num += 1;
            if num > 1000 {
                return Err("Too many backup files".to_string());
            }
        }
    }

    Ok(())
}

#[cfg(unix)]
fn is_same_file(path1: &Path, path2: &Path) -> io::Result<bool> {
    use std::os::unix::fs::MetadataExt;

    let meta1 = fs::metadata(path1)?;
    let meta2 = fs::metadata(path2)?;

    Ok(meta1.ino() == meta2.ino() && meta1.dev() == meta2.dev())
}

#[cfg(not(unix))]
fn is_same_file(_path1: &Path, _path2: &Path) -> io::Result<bool> {
    Ok(false)
}
